select t.* from ( select DISTINCT sat.alarm_type_id AS alarmTypeId, sat.type_name AS typeName, sat.icon AS icon, sat.type_value AS typeValue, sat.alarm_source AS alarmSource, sat.tenant_id AS tenantId, sat.industry_code AS industryCode, (SELECT is_visible FROM sys_alarm_type_industry_rel ir WHERE ir.industry_code = t1.industry_code AND ir.alarm_type_id = sat.alarm_type_id and ir.tenant_id = #{body.tenantId} ) AS isVisible FROM vm_order_algorithms t1 inner JOIN vm_algorithm_info_t t2 ON t1.algorithm_code = t2.algorithm_code inner JOIN vm_algorithm_alarm al ON t2.algo_min_type_code = al.algo_min_type inner JOIN sys_alarm_type sat ON al.alarm_type = sat.type_value WHERE sat.delete_flag = 0 and sat.alarm_source = '1' and t2.delete_flag = 0 and al.delete_flag = 0 and t1.delete_flag = 0 and t1.ord_status in (0, 1, 2) AND t1.tenant_id = #{body.tenantId} and t1.industry_code = #{body.industryCode}
AND sat.type_value IN
#{item}
${body.dataScope} ORDER BY sat.alarm_type_id ASC ) t
where t.isVisible = '1000' or t.isVisible is null
union select * from ( SELECT DISTINCT sat.alarm_type_id AS alarmTypeId, sat.type_name AS typeName, sat.icon AS icon, sat.type_value AS typeValue, sat.alarm_source AS alarmSource, sat.tenant_id AS tenantId, sat.industry_code AS industryCode, (SELECT is_visible FROM sys_alarm_type_industry_rel ir WHERE ir.alarm_type_id = sat.alarm_type_id and ir.industry_code = #{body.industryCode} and ir.tenant_id = #{body.tenantId} ) AS isVisible FROM sys_alarm_type sat WHERE (sat.delete_flag = 0 and sat.tenant_id is null and sat.industry_code is null
AND sat.type_value IN
#{item}
and (sat.app_ver_code = #{body.appVerCode} or sat.alarm_source in
#{alarmSource}
) ${body.dataScope} )) t
where t.isVisible = '1000' or t.isVisible is null
union select * from ( SELECT DISTINCT sat.alarm_type_id AS alarmTypeId, sat.type_name AS typeName, sat.icon AS icon, sat.type_value AS typeValue, sat.alarm_source AS alarmSource, sat.tenant_id AS tenantId, sat.industry_code AS industryCode, (SELECT is_visible FROM sys_alarm_type_industry_rel ir WHERE ir.alarm_type_id = sat.alarm_type_id and ir.industry_code = #{body.industryCode} and ir.tenant_id = #{body.tenantId} ) AS isVisible FROM sys_alarm_type sat WHERE sat.tenant_id = #{body.tenantId} and sat.industry_code = #{body.industryCode} and sat.delete_flag = 0 and sat.source != 3
AND sat.type_value IN
#{item}
${body.dataScope} ) t
where t.isVisible = '1000' or t.isVisible is null

select * from (
SELECT DISTINCT
sat.alarm_type_id AS alarmTypeId,
sat.type_name AS typeName,
sat.icon AS icon,
sat.type_value AS typeValue,
sat.alarm_source AS alarmSource,
sat.tenant_id AS tenantId,
sat.industry_code AS industryCode,
(SELECT is_visible FROM sys_alarm_type_industry_rel ir
WHERE ir.alarm_type_id = sat.alarm_type_id
and ir.industry_code = #{body.industryCode}
and ir.tenant_id = #{body.tenantId}
) AS isVisible
FROM sys_alarm_type sat
WHERE (sat.delete_flag = 0 and sat.tenant_id is null and sat.industry_code is null
and (sat.app_ver_code = #{body.appVerCode}
or sat.alarm_source in

    #{alarmSource}

)
)) t

    where t.isVisible = '1000' or t.isVisible is null


    union
    select * from (
    SELECT DISTINCT
    sat.alarm_type_id AS alarmTypeId,
    sat.type_name AS typeName,
    sat.icon AS icon,
    sat.type_value AS typeValue,
    sat.alarm_source AS alarmSource,
    sat.tenant_id AS tenantId,
    sat.industry_code AS industryCode,
    (SELECT is_visible FROM sys_alarm_type_industry_rel ir
    WHERE ir.alarm_type_id = sat.alarm_type_id
    and ir.industry_code = #{body.industryCode}
    and ir.tenant_id = #{body.tenantId}
    ) AS isVisible
