    and sat.industry_code = #{body.industryCode}
    and sat.delete_flag = 0
    ) t

        where t.isVisible = '1000' or t.isVisible is null

SELECT DISTINCT t4.tenant_id as customerCode, t4.thresh, t4.alarm_interval as alarmInterval, t4.alarm_interval_type as alarmIntervalType, t4.algorithm_time as algorithmTime FROM sys_alarm_type t3 LEFT JOIN sys_alarm_class_param t4 ON t3.alarm_type_id = t4.alarm_type_id WHERE t3.source='0' AND t3.delete_flag = '0' AND t4.tenant_id in
#{item}
AND t3.type_value = #{alarmType}

SELECT DISTINCT t.* FROM ( SELECT t.* FROM ( -- 第一个子查询 SELECT DISTINCT sat.alarm_type_id AS alarmTypeId, sat.type_name AS alarmTypeName, sat.icon, sat.type_value AS typeValue, 'false' as modelAlgorithmFlag, d.alarmLevel, d.alarmLevelName, t1.tenant_id AS tenantId, i.tenant_name AS userName, i.province_id AS provinceId, i.city_id AS cityId, (SELECT is_visible FROM sys_alarm_type_industry_rel ir WHERE ir.industry_code = t1.industry_code AND ir.alarm_type_id = sat.alarm_type_id AND ir.tenant_id = #{body.tenantId}) AS isVisible FROM vm_order_algorithms t1 INNER JOIN vm_algorithm_info_t t2 ON t1.algorithm_code = t2.algorithm_code INNER JOIN vm_algorithm_alarm al ON t2.algo_min_type_code = al.algo_min_type INNER JOIN sys_alarm_type sat ON al.alarm_type = sat.type_value LEFT JOIN sys_alarm_type_level satl ON satl.type_value = sat.type_value AND satl.tenant_id = #{body.tenantId} AND satl.industry_code = #{body.industryCode} LEFT JOIN (SELECT DICT_VALUE AS alarmLevel, DICT_LABEL AS alarmLevelName FROM sys_dict_data WHERE DICT_TYPE = 'alarm_level') d ON COALESCE(satl.alarm_level, '1') = d.alarmLevel INNER JOIN sys_tenant_info i ON i.tenant_id = t1.tenant_id AND i.del_flag = '0'
LEFT JOIN sys_alarm_tags_type_rel tr ON sat.type_value = tr.type_value AND tr.tenant_id = t1.tenant_id AND tr.delete_flag = '0'
WHERE sat.delete_flag = 0 AND sat.alarm_source = '1' AND t2.delete_flag = 0 AND al.delete_flag = 0 AND t1.delete_flag = 0 AND t1.ord_status IN (0, 1, 2) AND t1.tenant_id = #{body.tenantId}
AND t1.industry_code = #{body.industryCode}
AND t1.tenant_id IN
#{labelIdItem}
AND sat.type_name LIKE CONCAT(CONCAT('%',#{body.alarmTypeName}),'%')
AND d.alarmLevel = #{body.alarmLevel}
AND i.province_id = #{body.provinceId}
AND i.city_id = #{body.cityId}
AND tr.tag_id IN
#{tagIdItem}
${body.dataScope} ) t WHERE 1=1
AND t.isVisible = #{body.isVisible}
AND (t.isVisible = '1000' OR t.isVisible IS NULL)
UNION -- 第二个子查询 SELECT * FROM ( SELECT DISTINCT sat.alarm_type_id AS alarmTypeId, sat.type_name AS alarmTypeName, sat.icon AS icon, sat.type_value AS typeValue, 'false' as modelAlgorithmFlag, d.alarmLevel, d.alarmLevelName, i.tenant_id AS tenantId, i.tenant_name AS userName, i.province_id AS provinceId, i.city_id AS cityId, (SELECT is_visible FROM sys_alarm_type_industry_rel ir WHERE ir.alarm_type_id = sat.alarm_type_id AND ir.industry_code = #{body.industryCode} AND ir.tenant_id = #{body.tenantId}) AS isVisible FROM sys_alarm_type sat LEFT JOIN sys_alarm_type_level satl ON satl.type_value = sat.type_value AND satl.tenant_id = #{body.tenantId} AND satl.industry_code = #{body.industryCode} LEFT JOIN (SELECT DICT_VALUE AS alarmLevel, DICT_LABEL AS alarmLevelName FROM sys_dict_data WHERE DICT_TYPE = 'alarm_level') d ON COALESCE(satl.alarm_level, '1') = d.alarmLevel LEFT JOIN sys_tenant_info i ON i.tenant_id = #{body.tenantId} AND i.del_flag = '0'
LEFT JOIN sys_alarm_tags_type_rel tr ON sat.type_value = tr.type_value AND tr.tenant_id = i.tenant_id AND tr.delete_flag = '0'
WHERE (sat.delete_flag = 0 AND sat.tenant_id IS NULL AND sat.industry_code IS NULL AND sat.alarm_source IN #{alarmSource}
)
AND sat.type_name LIKE CONCAT(CONCAT('%',#{body.alarmTypeName}),'%')
AND d.alarmLevel = #{body.alarmLevel}
AND tr.tag_id IN
#{tagIdItem}
${body.dataScope} ) t WHERE 1=1
AND t.isVisible = #{body.isVisible}
AND (t.isVisible = '1000' OR t.isVisible IS NULL)
UNION -- 第三个子查询 SELECT * FROM ( SELECT DISTINCT sat.alarm_type_id AS alarmTypeId, sat.type_name AS alarmTypeName, sat.icon AS icon, sat.type_value AS typeValue, 'false' as modelAlgorithmFlag, d.alarmLevel, d.alarmLevelName, i.tenant_id AS tenantId, i.tenant_name AS userName, i.province_id AS provinceId, i.city_id AS cityId, (SELECT is_visible FROM sys_alarm_type_industry_rel ir WHERE ir.alarm_type_id = sat.alarm_type_id AND ir.industry_code = #{body.industryCode} AND ir.tenant_id = #{body.tenantId}) AS isVisible FROM sys_alarm_type sat LEFT JOIN sys_alarm_type_level satl ON satl.type_value = sat.type_value AND satl.tenant_id = #{body.tenantId} AND satl.industry_code = #{body.industryCode} LEFT JOIN (SELECT DICT_VALUE AS alarmLevel, DICT_LABEL AS alarmLevelName FROM sys_dict_data WHERE DICT_TYPE = 'alarm_level') d ON COALESCE(satl.alarm_level, '1') = d.alarmLevel LEFT JOIN sys_tenant_info i ON i.tenant_id = #{body.tenantId} AND i.del_flag = '0'
LEFT JOIN sys_alarm_tags_type_rel tr ON sat.type_value = tr.type_value AND tr.tenant_id = i.tenant_id AND tr.delete_flag = '0'
WHERE sat.delete_flag = 0 and sat.source != 3 AND sat.tenant_id = #{body.tenantId} AND sat.industry_code = #{body.industryCode}
AND sat.type_name LIKE CONCAT(CONCAT('%',#{body.alarmTypeName}),'%')
AND d.alarmLevel = #{body.alarmLevel}
AND tr.tag_id IN
#{tagIdItem}
${body.dataScope} ) t WHERE 1=1
AND t.isVisible = #{body.isVisible}
AND (t.isVisible = '1000' OR t.isVisible IS NULL)
UNION -- 第四个子查询 SELECT t.* FROM ( SELECT DISTINCT sat.alarm_type_id AS alarmTypeId, sat.type_name AS alarmTypeName, sat.icon, sat.type_value AS typeValue, 'true' as modelAlgorithmFlag, d.alarmLevel, d.alarmLevelName, t1.tenant_id AS tenantId, i.tenant_name AS userName, i.province_id AS provinceId, i.city_id AS cityId, (SELECT is_visible FROM sys_alarm_type_industry_rel ir WHERE ir.industry_code = t1.industry_code AND ir.alarm_type_id = sat.alarm_type_id AND ir.tenant_id = #{body.tenantId}) AS isVisible FROM vm_order_algorithms t1 inner join sys_scene_config sc on t1.tenant_id = sc.tenant_id and t1.industry_code = sc.industry_code and t1.algorithm_code = sc.algorithm_code and sc.delete_flag = 0 inner join sys_alarm_type sat on sc.type_value = sat.type_value and sat.delete_flag = 0 and ((sat.source = 3 and sat.tenant_id = t1.tenant_id and sat.industry_code = t1.industry_code) or sat.source != 3) LEFT JOIN sys_alarm_type_level satl ON satl.type_value = sat.type_value AND satl.tenant_id = #{body.tenantId} AND satl.industry_code = #{body.industryCode} LEFT JOIN (SELECT DICT_VALUE AS alarmLevel, DICT_LABEL AS alarmLevelName FROM sys_dict_data WHERE DICT_TYPE = 'alarm_level') d ON COALESCE(satl.alarm_level, '1') = d.alarmLevel INNER JOIN sys_tenant_info i ON i.tenant_id = t1.tenant_id AND i.del_flag = '0'
LEFT JOIN sys_alarm_tags_type_rel tr ON sat.type_value = tr.type_value AND tr.tenant_id = t1.tenant_id AND tr.delete_flag = '0'
WHERE sat.delete_flag = 0 AND sat.alarm_source = '1' AND t1.delete_flag = 0 AND t1.ord_status IN (0, 1, 2) and t1.tenant_id = #{body.tenantId} and t1.industry_code = #{body.industryCode} and t1.ord_status in (0,1,2) and t1.algorithm_code in
#{item}
AND t1.tenant_id IN
#{labelIdItem}
AND sat.type_name LIKE CONCAT(CONCAT('%',#{body.alarmTypeName}),'%')
AND d.alarmLevel = #{body.alarmLevel}
AND i.province_id = #{body.provinceId}
AND i.city_id = #{body.cityId}
AND tr.tag_id IN
#{tagIdItem}
${body.dataScope} ) t WHERE 1=1
AND t.isVisible = #{body.isVisible}
AND (t.isVisible = '1000' OR t.isVisible IS NULL)
) t
ORDER BY t.alarmLevel
DESC
ASC
ORDER BY t.alarmTypeId ASC

