select al.type_value, al.type_name, 'true' as modelAlgorithmFlag, o.algorithm_code algorithmCode, al.alarm_type_id alarmTypeId from vm_order_algorithms o inner join sys_scene_config sc on o.tenant_id = sc.tenant_id and o.industry_code = sc.industry_code and o.algorithm_code = sc.algorithm_code and sc.delete_flag = 0 inner join sys_alarm_type al on sc.type_value = al.type_value and al.delete_flag = 0 and ((al.source = '3' and al.tenant_id = o.tenant_id and al.industry_code = o.industry_code) or al.source != '3') where o.tenant_id = #{tenantId} and o.industry_code = #{industryCode} and o.ord_status in (0,1,2) and o.algorithm_code in
#{item}
group by al.type_value
